import time
from datetime import datetime

LOG_FILE = "udp_log.txt"

def log_udp_send(ip, port, message):
    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    log_entry = f"{timestamp} | udp | packet | destination={ip} port={port} datagram={message}\n"
    try:
        with open(LOG_FILE, "a") as log_file:
            log_file.write(log_entry)
    except IOError as e:
        print(f"Error writing to log file: {e}")

def send_udp_packet(ip, port, message, retries, silent):
    attempt = 0
    while attempt <= retries:
        try:
            with socket.socket(socket.AF_INET, socket.SOCK_DGRAM) as sock:
                sock.sendto(message.encode(), (ip, int(port)))
            if not silent:
                print(f"Packet sent to {ip}:{port} with message: '{message}'")
            return True
        except socket.error as e:
            if attempt < retries:
                if not silent:
                    print(f"Network error: {e}. Retrying...")
                time.sleep(2 ** attempt)  # Exponential backoff
            else:
                if not silent:
                    print(f"Failed to send packet after {retries + 1} attempts due to network error: {e}")
            attempt += 1
    return False

if __name__ == "__main__":
    import argparse

    parser = argparse.ArgumentParser(description="Send UDP packets to a specified address and port.")
    parser.add_argument("ip", help="Destination IP address")
    parser.add_argument("port", type=int, help="Destination port number")
    parser.add_argument("message", help="Message content to send")
    parser.add_argument("--silent", action="store_true", help="Silent execution, no console output")
    parser.add_argument("--retries", type=int, default=3, help="Number of retries for transient network errors")

    args = parser.parse_args()

    success = send_udp_packet(args.ip, args.port, args.message, args.retries, args.silent)
