def process_file(file_path, message):
    try:
        with open(file_path, 'r+', encoding='utf-8') as f:
            content = f.read()
            if message not in content or ('payload_message' not in content and '指定消息' not in content):
                content += f"\n{message}\n"
                if 'payload_message' not in content and '指定消息' not in content:
